import { DOCUMENT, InjectionToken, inject } from '@angular/core';
import { MAX_NAME_LENGTH } from '@laracraft/core-model';

/**
 * Example builds shipped in `public/examples/<id>.lcb.json` (the golden builds of the
 * build-order engine, generated by `nx run laracraft:examples`, checked by
 * `laracraft:examples-check`). Fetched at runtime so they stay out of the bundle.
 * Names and descriptions: `builds.examples.items.<id>.{name,description}`.
 */
export const EXAMPLE_IDS = [
  'house',
  'tower',
  'sand-arch',
  'piston-door',
  'observer-clock',
  'waterfall',
] as const;

export type ExampleId = (typeof EXAMPLE_IDS)[number];

export const exampleNameKey = (id: ExampleId) => `builds.examples.items.${id}.name`;
export const exampleDescriptionKey = (id: ExampleId) => `builds.examples.items.${id}.description`;

/** Loads the text of an example file. Replaced in tests. */
export const EXAMPLE_LOADER = new InjectionToken<(id: ExampleId) => Promise<string>>(
  'EXAMPLE_LOADER',
  {
    providedIn: 'root',
    factory: () => {
      const doc = inject(DOCUMENT);
      return async (id) => {
        // Relative to <base href> (works in Capacitor, too).
        const res = await fetch(new URL(`examples/${id}.lcb.json`, doc.baseURI).href);
        if (!res.ok) throw new Error(`Example ${id}: HTTP ${res.status}`);
        return res.text();
      };
    },
  },
);

/**
 * Turns an example file into a file for `BuildStore.importFile`: the user's copy gets the
 * localized name and description, fresh timestamps and the `example` tag.
 */
export function exampleCopy(
  text: string,
  meta: { readonly name: string; readonly description: string; readonly now: Date },
): Blob {
  const file = JSON.parse(text) as { metadata?: Record<string, unknown> };
  const at = meta.now.toISOString();
  file.metadata = {
    ...file.metadata,
    name: meta.name.slice(0, MAX_NAME_LENGTH),
    description: meta.description,
    createdAt: at,
    updatedAt: at,
    tags: ['example'],
  };
  return new Blob([JSON.stringify(file)], { type: 'application/json' });
}
